import * as Shox from "https://cdn.jsdelivr.net/npm/shox@1.2.0/src/Shox.js"
import { random } from "./tools.js"

const luminance = `
	float luminance(vec3 color) {
		return dot(color, vec3(0.2126, 0.7152, 0.0722));
	}
`

const brightnessGradient = `
	vec2 brightnessGradient(vec2 uv, sampler2D textureSampler, vec2 ts) {
		float c = luminance(texture(textureSampler, uv).rgb);

		float l = luminance(texture(textureSampler, uv + ts*vec2(-1., 0.)).rgb);
		float r = luminance(texture(textureSampler, uv + ts*vec2(1., 0.)).rgb);
		float t = luminance(texture(textureSampler, uv + ts*vec2(0., 1.)).rgb);
		float b = luminance(texture(textureSampler, uv + ts*vec2(0., -1.)).rgb);

		float gx = (r-l)/2.;
		float gy = (t-b)/2.;

		return vec2(gx, gy);
	}
`

const normalMap = `
	vec3 normalMap(vec2 uv, sampler2D tex, vec2 texelSize, float scale) {
		vec2 d = vec2(
			luminance( texture(tex, uv + vec2(texelSize.x, 0)).rgb ) -
			luminance( texture(tex, uv - vec2(texelSize.x, 0)).rgb ),
			luminance( texture(tex, uv + vec2(0, texelSize.y)).rgb ) -
			luminance( texture(tex, uv - vec2(0, texelSize.y)).rgb )
		);

		return .5+.5*normalize(vec3(-d*scale, 1.));
	}
`

const noise = `
	vec4 noise(vec2 uv, float scal, float gain, float ofst, vec3 move) {
		vec4 noise;
		noise  =      1.*snoise3DImage((uv-vec2(421., 132.))*1., scal, gain, ofst, move);
		noise +=      .5*snoise3DImage((uv-vec2(913., 687.))*2., scal, gain, ofst, move);
		noise +=     .25*snoise3DImage((uv-vec2(834., 724.))*4., scal, gain, ofst, move);
		noise +=    .125*snoise3DImage((uv-vec2(125., 209.))*8., scal, gain, ofst, move);
		noise +=   .0625*snoise3DImage((uv-vec2(387., 99.))*16., scal, gain, ofst, move);
		noise +=  .03125*snoise3DImage((uv-vec2(99., 387.))*32., scal, gain, ofst, move);
		noise /= 1.+.5+.25+.125+.0625+.03125;
		return noise;
	}
`

const pal = (t) => `
vec4(palette(${t},
	vec3(${random(0.25, 0.75)}, ${random(0.25, 0.75)}, ${random(0.25, 0.75)}),
	vec3(${random()}, ${random()}, ${random()}),
	vec3(${random(1, 5)}, ${random(1, 5)}, ${random(1, 5)}),
	vec3(${random()}, ${random()}, ${random()})
), 1.)
`

export const BASE_FRAG = `
	precision mediump float;

	in vec2 vTexCoord;

	${Shox.hash}
	${Shox.noiseMath}
	${Shox.snoise3D}
	${Shox.snoise3DImage}
	${Shox.iqPalette}
	${noise}

	out vec4 fragColor;
	void main() {
		vec2 uv = vTexCoord;
		float h = hash12(uv*3141.5926);
		fragColor = vec4(vec3(h), 1.);
		vec4 n = noise(uv, 10., 20., .5, vec3(${random(0, 1000)}));
		fragColor = ${pal("n.r")};
	}
	`

export const ITER_FRAG = `
	precision mediump float;

	in vec2 vTexCoord;
	uniform sampler2D uImage;
	uniform float time;

	${Shox.hash}
	${Shox.noiseMath}
	${Shox.snoise3D}
	${Shox.snoise3DImage}
	${Shox.imageExtend}
	${Shox.displace}
	${noise}
	${luminance}
	${brightnessGradient}

	out vec4 fragColor;
	void main() {
		vec2 uv = vTexCoord;
		vec2 texelSize = 1./vec2(textureSize(uImage, 0));
		vec2 h = hash22(uv*3141.5926);

		float scal = ${random(1, 10)};
		float gain = ${random(0, 0.5)};
		float ofst = .5;
		vec3  move = vec3(0., 0., time*.1);

		vec4 n1 = noise(uv, scal, gain, ofst, move);
		vec2 dimgUV = displace(uv, n1.rg, ofst, 2.);
		dimgUV = displace(dimgUV, h, ofst, .1);
		vec4 dimg = noise(dimgUV, scal, gain, ofst, move);

		vec2 slope = brightnessGradient(uv, uImage, texelSize*${random(0, 5)})+.5;
		vec2 g = vec2(slope.x, slope.y);

		float wei = .005;
		vec2 duv = displace(
			displace(uv, g.rg, ofst, 0.01)
			, dimg.rg, ofst, wei);

		vec4 col = texture(uImage, duv);
		fragColor = col;//+h.x*0.01;
	}
	`

export const QUAD_FRAG = `
	precision mediump float;

	in vec2 vTexCoord;

	uniform sampler2D uImage;

	${Shox.hash}
	${Shox.iqPalette}
	${luminance}
	${normalMap}

	out vec4 fragColor;
	void main() {
		vec2 uv = vTexCoord;
		vec2 texelSize = 1./vec2(textureSize(uImage, 0));
		vec2 h = hash22(uv*3141.5926);

		vec3  LIGHT_COLOR    = vec3(1., 1., 1.);
		vec3  AMBIENT_COLOR  = vec3(.1, .1, .1);
		vec3  SPECULAR_COLOR = vec3(1., 1., 1.);
		vec3  DIFFUSE_COLOR  = ${pal("texture(uImage, uv).r")}.rgb;
		float SHININESS      = ${random(32, 128)};

		vec3 p = vec3(uv, 0.);
		vec3 LightPos = vec3( ${random(0.25, 0.75)}, ${random(0.25, 0.75)}, 1.);
		vec3 ViewPos  = LightPos;

		vec3 LightDir = normalize( LightPos - p );
		vec3 ViewDir  = normalize( ViewPos  - p );
		vec3 HalfDir  = normalize( LightDir + ViewDir );

		vec3 Normal = normalMap(uv, uImage, texelSize, 50.);
		Normal = 2.*Normal-1.;

		float diffuseFactor  = max(dot(Normal, LightDir), 0.);
		vec3  diffuse  = DIFFUSE_COLOR  * LIGHT_COLOR * diffuseFactor;

		float specularFactor = pow(max(dot(Normal, HalfDir), 0.), SHININESS);
		vec3  specular = SPECULAR_COLOR * LIGHT_COLOR * specularFactor;

		vec3  color = AMBIENT_COLOR + diffuse + specular;

		fragColor = vec4(color, 1.);
	}
`

export const QUAD_VERT = `

	in vec4 aPosition;
	in vec2 aTexCoord;

	out vec2 vTexCoord;
	void main() {
		vTexCoord = aTexCoord;
		gl_Position = aPosition;
	}
`


// === Tab: tools.js ===
export const random = (min = 0, max = 1) => {
	return Math.random() * (max - min) + min
}

export const floor = (value) => {
	return Math.floor(value)
}

export const min = (value1, value2) => {
	return Math.min(value1, value2)
}

export const pow = (x, y) => {
	return Math.pow(x, y)
}

